create or alter procedure [graph].[Hop_LoadNextHopAssets]
	@direction char(1),
	@hopNumber int,
	@maxNodeTableRowId int,
	@leafOnly bit
as
begin
	insert into #hopAssets
		select	AssetID, [Key], @direction, @hopNumber
		from	(
				select	*,
						ROW_NUMBER() OVER ( PARTITION BY AssetID, [Level] ORDER BY [Position] DESC ) AS Row_Num
				from	(
						select	distinct
								L.AssetID
								,L.[Key]
								,L.[Level]
								,L.[Position]
								,A.AssetTypeClass
								,L.IsLeaf
						from	#nodes L
								inner join AssetWithType A on A.ID = L.AssetID and L.RowId > @maxNodeTableRowId
				) I
				) O where Row_Num = 1 and ( 
											(@leafOnly = 1 and IsLeaf = 1)
											or (@leafOnly = 0 and 1 = 1)
										  );
end
